// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['kick', 'promote', 'demote', 'tagall'], 'Group', 'Group admin actions', async (ctx) => {
  const { sock, from, msg, isGroup, body, cfg } = ctx;
  const cmd = body.slice((ctx.settings.prefix || cfg.prefix).length).trim().split(/\s+/)[0].toLowerCase();
  if (!isGroup) return sock.sendMessage(from, { text: 'This only works in groups.' }, { quoted: msg });

  const meta = await sock.groupMetadata(from);
  const botJid = sock.user.id.split(':')[0] + '@s.whatsapp.net';
  const botIsAdmin = meta.participants.some(p => p.id === botJid && p.admin);
  if (!botIsAdmin) return sock.sendMessage(from, { text: '⚠️ I need to be a group admin to do that.' }, { quoted: msg });

  if (cmd === 'tagall') {
    const text = meta.participants.map(p => `@${p.id.split('@')[0]}`).join(' ');
    return sock.sendMessage(from, { text, mentions: meta.participants.map(p => p.id) });
  }

  const mentioned = msg.message.extendedTextMessage?.contextInfo?.mentionedJid || [];
  if (!mentioned.length) return sock.sendMessage(from, { text: `Tag the user(s) you want to ${cmd}.` }, { quoted: msg });

  if (cmd === 'kick') { await sock.groupParticipantsUpdate(from, mentioned, 'remove'); return sock.sendMessage(from, { text: `✅ Removed ${mentioned.length} member(s).` }); }
  if (cmd === 'promote') { await sock.groupParticipantsUpdate(from, mentioned, 'promote'); return sock.sendMessage(from, { text: '✅ Promoted.' }); }
  if (cmd === 'demote') { await sock.groupParticipantsUpdate(from, mentioned, 'demote'); return sock.sendMessage(from, { text: '✅ Demoted.' }); }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
